export type LegalPath = '/oferta' | '/privacy' | '/consent' | '/ads-consent'

/** Таблица внутри раздела: строка заголовков и строки данных. */
export type LegalTable = { head: string[]; rows: string[][] }

/** Блок раздела: абзац (с номером пункта в начале или без) или таблица. */
export type LegalBlock = string | { table: LegalTable }

/** Раздел: заголовок с номером, как у юристов («2. Тарифы стоимость и оплата»). */
export type LegalSection = { title: string; blocks: LegalBlock[] }

/** Текст документа — дословно из docx юристов. */
export type LegalText = {
  /** Заголовок документа — он же заголовок страницы. */
  title: string
  /** Абзацы до первого раздела. */
  intro: string[]
  sections: LegalSection[]
}

export type LegalDoc = LegalText & {
  path: LegalPath
  /** Короткое имя для ссылок между документами внизу страницы. */
  short: string
  /** Строка под заголовком: что это за документ (наша, не юристов). */
  lead: string
  /**
   * Заголовок карточки реквизитов внизу страницы. null — у документа свой
   * раздел реквизитов (оферта, раздел 11), и карточка показывает только
   * ссылки на другие документы.
   */
  requisitesTitle: string | null
}

